/**
 * GitHub Action Script: Post Benchmark Comment
 *
 * Posts (or updates) a single sticky PR comment with the benchmark comparison rendered by
 * excalibur-benchmark (`bench.mjs report --markdown`). The comment is found again on later runs through the
 * hidden marker so a PR only ever has one benchmark comment.
 *
 * Executed by github-script@v7 in the benchmark workflow.
 *
 * @param {Object} github - GitHub API client (octokit)
 * @param {Object} context - GitHub Actions context
 */
module.exports = async ({ github, context }) => {
  const fs = require('fs');
  const MARKER = '<!-- excalibur-benchmark -->';
  const REPORT_PATH = './bench-results/report.md';
  const MAX_BODY = 60_000; // GitHub comments cap at 65536 chars

  const workflowUrl = `${process.env.GITHUB_SERVER_URL}/${process.env.GITHUB_REPOSITORY}/actions/runs/${process.env.GITHUB_RUN_ID}`;
  const commitSha = process.env.GITHUB_HEAD_SHA || process.env.GITHUB_SHA;

  let report;
  if (fs.existsSync(REPORT_PATH)) {
    report = fs.readFileSync(REPORT_PATH, 'utf8');
  } else {
    report = '### Excalibur benchmark\n\nThe benchmark run produced no report, check the workflow logs.';
  }
  // Security: the report is generated by our own tool from numbers, but strip anything that could close the
  // marker comment or inject html
  report = report.replace(/<!--/g, '&lt;!--').replace(/--!?>/g, '--&gt;');
  if (report.length > MAX_BODY) {
    report = report.substring(0, MAX_BODY) + '\n\n_(report truncated, see the artifact)_';
  }

  const trigger = process.env.BENCHMARK_TRIGGER ? `Triggered by ${process.env.BENCHMARK_TRIGGER}. ` : '';
  const body = [
    MARKER,
    report,
    '',
    trigger
      ? `<sub>${trigger}Comment \`/benchmark [--baseline npm:excalibur@<version>] [--tests a,b] [--repeat n]\` to run again.</sub>`
      : '<sub>Comment `/benchmark [--baseline npm:excalibur@<version>] [--tests a,b] [--repeat n]` to run again.</sub>',
    `<sub>Commit ${commitSha ? commitSha.substring(0, 7) : 'unknown'} · [workflow run](${workflowUrl}) · charts and raw results are in the \`benchmark-results\` artifact · informational only</sub>`
  ].join('\n');

  const issue_number = context.issue.number;
  if (!issue_number) {
    console.log('No PR number in context, skipping comment');
    return;
  }

  const comments = await github.paginate(github.rest.issues.listComments, {
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number,
    per_page: 100
  });
  const existing = comments.find((c) => c.body && c.body.startsWith(MARKER));

  if (existing) {
    await github.rest.issues.updateComment({ owner: context.repo.owner, repo: context.repo.repo, comment_id: existing.id, body });
    console.log(`Updated benchmark comment ${existing.id}`);
  } else {
    await github.rest.issues.createComment({ owner: context.repo.owner, repo: context.repo.repo, issue_number, body });
    console.log('Created benchmark comment');
  }
};
